# -*- coding: utf-8 -*-

SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="30" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">DOĞAL ÇEVRE VE BEŞERÎ ÇEVRE KAVRAMLARI</text>\n  <rect x="35" y="55" width="305" height="180" rx="8" fill="#f0fdf4" stroke="#22c55e"/>\n  <text x="187" y="80" text-anchor="middle" font-size="13" font-weight="bold" fill="#15803d">Doğal Çevre Unsurları (Kendiliğinden)</text>\n  <text x="55" y="108" font-size="11.5" fill="#334155">• Yeryüzü Şekilleri: Dağlar, ovalar, platolar, vadiler</text>\n  <text x="55" y="132" font-size="11.5" fill="#334155">• İklim Özellikleri: Sıcaklık, yağış, rüzgâr, nem</text>\n  <text x="55" y="156" font-size="11.5" fill="#334155">• Su Kaynakları: Denizler, akarsular, göller</text>\n  <text x="55" y="180" font-size="11.5" fill="#334155">• Doğal Bitki Örtüsü ve Toprak yapısı</text>\n  <text x="187" y="212" text-anchor="middle" font-size="11" font-weight="bold" fill="#166534">Örnek: Toros Dağları, Çukurova, Fırat Nehri</text>\n  <rect x="360" y="55" width="305" height="180" rx="8" fill="#eff6ff" stroke="#3b82f6"/>\n  <text x="512" y="80" text-anchor="middle" font-size="13" font-weight="bold" fill="#1d4ed8">Beşerî Çevre Unsurları (İnsan Eliyle)</text>\n  <text x="380" y="108" font-size="11.5" fill="#334155">• Yerleşme ve Konutlar: Şehirler, köyler, evler</text>\n  <text x="380" y="132" font-size="11.5" fill="#334155">• Ulaşım: Köprüler, tüneller, otoyollar, limanlar</text>\n  <text x="380" y="156" font-size="11.5" fill="#334155">• Ekonomik Tesisler: Fabrikalar, tarlalar, madenler</text>\n  <text x="380" y="180" font-size="11.5" fill="#334155">• Enerji ve Su Yapıları: Barajlar, sulama kanalları</text>\n  <text x="512" y="212" text-anchor="middle" font-size="11" font-weight="bold" fill="#1e40af">Örnek: Atatürk Barajı, Zigana Tüneli, Osman Gazi Köprüsü</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="30" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">TÜRKİYE\'DE GÖRÜLEN BAŞLICA İKLİM TİPLERİ VE ETKİLERİ</text>\n  <rect x="25" y="55" width="205" height="180" rx="8" fill="#f0fdf4" stroke="#22c55e"/>\n  <text x="127" y="80" text-anchor="middle" font-size="13" font-weight="bold" fill="#15803d">Karadeniz İklimi</text>\n  <text x="40" y="106" font-size="11" fill="#334155">• Her mevsim yağışlı, ılıman</text>\n  <text x="40" y="126" font-size="11" fill="#334155">• Bitki Örtüsü: Gür Ormanlar</text>\n  <text x="40" y="146" font-size="11" fill="#334155">• Ürün: Çay, fındık, mısır</text>\n  <text x="40" y="166" font-size="11" fill="#334155">• Konut: Ahşap, dik çatılı</text>\n  <text x="40" y="186" font-size="11" fill="#334155">• Yerleşme: Dağınık (engebeli</text>\n  <text x="50" y="202" font-size="11" fill="#475569">arazi ve bol su sebebiyle)</text>\n  <rect x="247" y="55" width="205" height="180" rx="8" fill="#fefce8" stroke="#eab308"/>\n  <text x="350" y="80" text-anchor="middle" font-size="13" font-weight="bold" fill="#a16207">Akdeniz İklimi</text>\n  <text x="262" y="106" font-size="11" fill="#334155">• Yazlar sıcak-kurak, kış ılık-yağışlı</text>\n  <text x="262" y="126" font-size="11" fill="#334155">• Bitki Örtüsü: Maki (kızılçam)</text>\n  <text x="262" y="146" font-size="11" fill="#334155">• Ürün: Zeytin, turunçgil, muz</text>\n  <text x="262" y="166" font-size="11" fill="#334155">• Konut: Taş meskenler</text>\n  <text x="262" y="186" font-size="11" fill="#334155">• Ekonomi: Seracılık ve yaz</text>\n  <text x="272" y="202" font-size="11" fill="#475569">turizmi çok gelişmiştir.</text>\n  <rect x="470" y="55" width="205" height="180" rx="8" fill="#eff6ff" stroke="#3b82f6"/>\n  <text x="572" y="80" text-anchor="middle" font-size="13" font-weight="bold" fill="#1d4ed8">Karasal İklim</text>\n  <text x="485" y="106" font-size="11" fill="#334155">• Yaz sıcak-kurak, kış soğuk-karlı</text>\n  <text x="485" y="126" font-size="11" fill="#334155">• Bitki Örtüsü: Bozkır (Step)</text>\n  <text x="485" y="146" font-size="11" fill="#334155">• Ürün: Buğday, arpa, şeker pancarı</text>\n  <text x="485" y="166" font-size="11" fill="#334155">• Konut: Kerpiç (toprak) evler</text>\n  <text x="485" y="186" font-size="11" fill="#334155">• Yerleşme: Toplu (su az, düz)</text>\n  <text x="485" y="206" font-size="11" fill="#475569">• Doğu Anadolu: Çayır / Büyükbaş</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="30" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">DOĞAL VE BEŞERÎ ÇEVRE ARASINDAKİ KARŞILIKLI ETKİLEŞİM</text>\n  <rect x="35" y="55" width="305" height="180" rx="8" fill="#eff6ff" stroke="#3b82f6"/>\n  <text x="187" y="80" text-anchor="middle" font-size="13" font-weight="bold" fill="#1d4ed8">Yeryüzü Şekilleri → Beşerî Faaliyet</text>\n  <text x="50" y="108" font-size="11.5" fill="#334155">• Geniş Ovalar (Çukurova, Konya, Bafra):</text>\n  <text x="60" y="126" font-size="11" fill="#475569">Tarım, sanayi, ulaşım kolay ve nüfus yoğundur.</text>\n  <text x="50" y="152" font-size="11.5" fill="#334155">• Yüksek ve Engebeli Alanlar (Hakkâri, Doğu</text>\n  <text x="60" y="170" font-size="11" fill="#475569">Karadeniz): Ulaşım zor, nüfus seyrek; kış turizmi,</text>\n  <text x="60" y="188" font-size="11" fill="#475569">yaylacılık, arıcılık ve hidroelektrik öne çıkar.</text>\n  <rect x="360" y="55" width="305" height="180" rx="8" fill="#fdf2f8" stroke="#ec4899"/>\n  <text x="512" y="80" text-anchor="middle" font-size="13" font-weight="bold" fill="#be185d">İnsanın Doğal Çevreye Müdahalesi</text>\n  <text x="375" y="108" font-size="11.5" fill="#334155">• Dağlar → Tüneller (Ovit, Zigana) ve viyadükler</text>\n  <text x="375" y="132" font-size="11.5" fill="#334155">• Boğaz ve Körfezler → Köprüler ve Avrasya Tüneli</text>\n  <text x="375" y="156" font-size="11.5" fill="#334155">• Deniz Doldurma → Ordu-Giresun ve Rize-Artvin</text>\n  <text x="385" y="174" font-size="11" fill="#475569">havalimanları (arazi darlığı sebebiyle)</text>\n  <text x="512" y="210" text-anchor="middle" font-size="11" font-weight="bold" fill="#9d174d">Sürdürülebilirlik: Doğaya zarar vermeden uyum!</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get("bolumler", [])):
        if i < len(SVGS):
            b["gorsel"] = SVGS[i]
